package com.example.starter.legality.api.dto;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotEmpty;

import java.util.List;

/**
 * 整组排班校验请求：一次提交机组成员名单及各自的值勤安排。
 */
public record CheckRequest(
        @NotEmpty(message = "duties 不能为空")
        @Valid
        List<MemberDutyRequest> duties
) {
}

package com.example.starter.legality.api.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

import java.time.Instant;

/**
 * 单个机组成员的值勤提交；时刻均为带偏移的 ISO-8601（建议 UTC，如 2026-09-20T06:00:00Z）。
 *
 * @param requestId  客户端幂等键，指纹覆盖该字段
 * @param reportTime 报到时刻，FDP 起算点
 * @param plannedEnd 计划执勤结束时刻（不含延误延长）
 */
public record MemberDutyRequest(
        @NotBlank(message = "requestId 不能为空")
        String requestId,
        @NotBlank(message = "memberCode 不能为空")
        String memberCode,
        @NotBlank(message = "flightNo 不能为空")
        String flightNo,
        @NotNull(message = "reportTime 不能为空")
        Instant reportTime,
        @NotNull(message = "plannedEnd 不能为空")
        Instant plannedEnd
) {
}

package com.example.starter.legality.api.dto;

import java.time.Instant;
import java.util.List;

/**
 * 整组校验结论；任一名成员违规则 overallResult=ILLEGAL，且与各成员结果保持一致。
 */
public record CheckResponse(
        String batchId,
        String overallResult,
        boolean sealed,
        Instant finalizedAt,
        List<MemberDutyResponse> results
) {
}

package com.example.starter.legality.api.dto;

import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

/**
 * 延误延长上报。
 *
 * @param requestId     本次延误上报的幂等键
 * @param dutyRequestId 目标值勤记录提交时使用的 requestId
 * @param extensionMinutes 本次延长分钟数（正数）
 */
public record DelayRequest(
        @NotBlank(message = "requestId 不能为空")
        String requestId,
        @NotBlank(message = "dutyRequestId 不能为空")
        String dutyRequestId,
        @NotNull(message = "extensionMinutes 不能为空")
        @Min(value = 1, message = "extensionMinutes 必须为正数")
        Integer extensionMinutes,
        String note
) {
}

package com.example.starter.legality.api.dto;

import java.time.Instant;
import java.util.List;

/**
 * 延误上报处理结果。
 *
 * @param late                  封板后补交为 true（迟到留痕，不推翻已封板结论）
 * @param accepted              延长是否被受理（重放或迟到留痕亦返回首次/既有状态）
 * @param idempotentReplay      是否同键重放
 * @param result                关联值勤记录当前结论
 * @param reasons               重新核算后（或既有）的违规原因
 */
public record DelayResponse(
        String requestId,
        String dutyRequestId,
        int extensionMinutes,
        int totalExtensionMinutes,
        Instant dutyEnd,
        boolean late,
        boolean accepted,
        String result,
        List<String> reasons,
        boolean idempotentReplay
) {
}

