/**
 * FDP 合规规则：报到时段分档、每日延长上限、7 日工时上限与最短休息期。
 * 时刻均以 UTC 存储；报到分档按起飞机场本地时区。
 */
@Component
public class LegalityRules {

    /** 每日历日（UTC）累计延长上限：2 小时（含边界，恰满合法） */
    public static final int DAILY_EXTENSION_LIMIT_MINUTES = 120;
